/// ─────────────────────────────────────────────────────────────────────────────
/// MediHive — the same documents the backend's own tier reads
///
/// Three files, copied byte for byte out of `hms_v2/test/fixtures/`, which is
/// where `generate-documents.py` writes them and where `verify-patient-
/// documents.ts` reads them from. Deliberately the **same** documents rather
/// than new ones: the mobile tier and the live tier should be exercising one
/// prescription, so that a difference between them is a difference in the
/// software rather than in the paper.
///
/// ## Why they are base64 in a Dart file
///
/// An integration test runs on the device, and the only bytes it can reach are
/// the ones in the app's asset bundle — so a real `.png` here would have to be
/// declared in `pubspec.yaml`, which ships a quarter of a megabyte of test
/// images inside every release build. Embedded here they stay in the test tree,
/// which is where they belong.
///
/// ## Regenerating
///
/// ```sh
/// python3 ../hms_v2/test/fixtures/generate-documents.py
/// # then re-run the base64 step that produced this file
/// ```
///
/// A 1x1 placeholder was what this used to be, and it was wrong for two
/// reasons: the quality check on the server refuses an image that small with a
/// written sentence about holding the camera closer, so the placeholder could
/// only ever exercise the refusal; and an upload of sixty-nine bytes does not
/// produce a progress bar anybody can see move.
/// ─────────────────────────────────────────────────────────────────────────────
library;

import 'dart:convert';
import 'dart:typed_data';

/// A printed prescription: two medicines, a prescriber, a facility and a date.
/// The document every extraction assertion in this tier is about.
///
/// 104139 bytes.
final Uint8List kPrescriptionPng = base64Decode(_prescriptionPngBase64);

/// The same prescription as a PDF, for the third way in. 105988 bytes.
final Uint8List kPrescriptionPdf = base64Decode(_prescriptionPdfBase64);

/// A thumbnail of a page: legible to nobody, and the case §5 refuses **before**
/// OCR rather than after. A recogniser handed this comes back at plausible
/// confidence about the wrong characters, and no number downstream can separate
/// that from a good read.
///
/// 21203 bytes.
final Uint8List kTooSmallPng = base64Decode(_tooSmallPngBase64);

